function def = f90_xtherm05_definition
%F90_XTHERM05_DEFINITION Distributed battery cooling-plate task contract.

def = struct;
def.id = "XTHERM05";
def.formal_id = "F90-XTHERM-05";
def.reference_role = "benchmark_reference";
def.sim = struct("start",0,"stop",240,"max_step",1.0);
def.source = struct( ...
    "url","https://github.com/simscape/Battery-Cooling-Plate-Simscape", ...
    "tag","25.1.1.1", ...
    "commit","f82fcc5454dd5ae273f752d1a1d82776e91c4f7c", ...
    "license","BSD-3-Clause", ...
    "project","reference/files/Battery-Cooling-Plate-Simscape/" + ...
        "BatteryCoolingPlateSimscape.prj", ...
    "exact_model","reference/files/Battery-Cooling-Plate-Simscape/Model/" + ...
        "PouchBatteryPack96S3PWithCustomCoolingPlateForCharging.slx", ...
    "exact_file_presence","present");

def.public_inputs = [ ...
    pin("coolant_flow_lpm",1.00,0.60,1.80,"L/min", ...
        "commanded coolant volume flow through the plate"), ...
    pin("coolant_inlet_temperature_K",293.15,288.15,303.15,"K", ...
        "coolant temperature at the plate inlet reservoir"), ...
    pin("charge_current_A",234,40,260,"A", ...
        "total-pack charging-current limit before the scheduled command change"), ...
    pin("charge_step_fraction",0.10,-0.20,0.20,"1", ...
        "fractional change of the charging-current limit"), ...
    pin("charge_step_time_s",120,80,160,"s", ...
        "time of the charging-current-limit change"), ...
    pin("initial_battery_temperature_K",303.15,298.15,313.15,"K", ...
        "common initial temperature of the battery thermal nodes"), ...
    pin("max_cell_voltage_V",4.10,4.00,4.20,"V", ...
        "maximum cell-equivalent voltage setting for charging")];

def.outputs = [ ...
    pout("battery_temperature",24,"K", ...
        "24 independently evolved battery thermal-node measurements"), ...
    pout("plate_temperature",24,"K", ...
        "24 measured temperatures of the finite-capacity plate partitions"), ...
    pout("coolant_temperature_rise",1,"K", ...
        "thermal-liquid outlet-minus-inlet temperature measurement"), ...
    pout("coolant_pressure_drop",1,"bar", ...
        "thermal-liquid inlet-to-outlet pressure-drop measurement"), ...
    pout("pack_current",1,"A", ...
        "total current measured in the physical battery electrical path"), ...
    pout("cell_equivalent_voltage",1,"V", ...
        "mean cell-equivalent voltage derived from physical pack voltage measurements")];

def.prompt = strjoin([ ...
    "Build a physically causal liquid-cooled 96-series, 3-parallel pouch-cell battery pack for controlled charging. The electrical pack and its distributed thermal model must be coupled so that charging losses create heat in the same battery elements whose temperatures are reported.", ...
    "The thermal path must contain independently evolving battery thermal nodes, conductive coupling into a finite-heat-capacity plate with 24 spatial partitions, and a real through-flow coolant network with finite hydraulic pressure loss. The electrical source must deliver power through the physical pack. A controller must use measured electrical feedback to limit charging current and transition toward the declared cell-equivalent voltage ceiling; the controller design is otherwise unrestricted.", ...
    "Read coolant_flow_lpm, coolant_inlet_temperature_K, charge_current_A, charge_step_fraction, charge_step_time_s, initial_battery_temperature_K, and max_cell_voltage_V from MATLAB base-workspace variables. charge_current_A is the total-pack charging-current limit, not a per-branch current. Their nominal values are 1.00 L/min, 293.15 K, 234 A, 0.10, 120 s, 303.15 K, and 4.10 V. Their valid ranges are respectively 0.60--1.80 L/min, 288.15--303.15 K, 40--260 A, -0.20--0.20, 80--160 s, 298.15--313.15 K, and 4.00--4.20 V. At charge_step_time_s the total-pack current limit changes from charge_current_A to charge_current_A*(1+charge_step_fraction).", ...
    "Across the declared range, the pack must charge with bounded current and voltage while the coolant removes heat from the distributed battery nodes. Increasing coolant flow must act through the physical fluid path and change both measured pressure loss and thermal response. Temperature fields must remain finite and spatially meaningful; prescribed output waveforms, duplicated temperature channels, command copies, and lookup-only plant surrogates are not valid implementations.", ...
    "Log Timeseries battery_temperature with 24 channels in kelvin, plate_temperature with 24 channels in kelvin, coolant_temperature_rise with one channel in kelvin, coolant_pressure_drop with one channel in bar, pack_current with one channel in total-pack amperes, and cell_equivalent_voltage with one channel in volts. Temperature channels must come from the stated battery nodes and plate partitions, coolant quantities from physical inlet/outlet sensing, and electrical quantities from the physical pack path.", ...
    "Work directly in the required model file and keep the latest usable state saved at that path throughout the task."], sprintf("\n\n"));

def.scenarios = [ ...
    scenario("hot_low_flow", values(.62,300.15,258,.18,104,312.15,4.18)), ...
    scenario("cold_high_flow", values(1.76,288.50,170,-.15,151,299.00,4.02)), ...
    scenario("high_current_boundary", values(1.08,294.15,260,.16,91,306.15,4.16)), ...
    scenario("flow_pair_low", values(.66,293.15,234,.10,120,303.15,4.10)), ...
    scenario("flow_pair_high", values(1.66,293.15,234,.10,120,303.15,4.10)), ...
    scenario("current_pair_up", values(1.00,293.15,50,.20,120,303.15,4.10)), ...
    scenario("current_pair_control", values(1.00,293.15,50,0,120,303.15,4.10)), ...
    scenario("current_pair_down", values(1.00,293.15,50,-.20,120,303.15,4.10)), ...
    scenario("warm_inlet_boundary", values(1.28,302.50,246,-.12,139,310.15,4.12))];

def.groups = struct( ...
    "G","runnable physical model, complete Timeseries contract and core-path qualification", ...
    "A","nominal charging and initial-condition accuracy", ...
    "Q","nominal battery/plate temperature-field quality", ...
    "M","distributed electro-thermal-fluid mechanism and causal perturbation response", ...
    "R","worst required operating-point robustness", ...
    "D","CC-active low-limit triplet with 1:1 total-pack ampere response", ...
    "weights",struct("A",.20,"Q",.17,"M",.25,"R",.23,"D",.15));
end

function s = pin(name, nominal, minv, maxv, unit, meaning)
s = struct("name",name,"nominal",nominal,"min",minv,"max",maxv, ...
    "unit",unit,"meaning",meaning);
end

function s = pout(name, channels, unit, source)
s = struct("name",name,"channels",channels,"unit",unit, ...
    "physical_source",source);
end

function s = scenario(id, scenarioValues)
s = struct("id",id,"values",scenarioValues);
end

function v = values(flow, inletT, current, stepFraction, stepTime, initialT, maxV)
v = struct( ...
    "coolant_flow_lpm",flow, ...
    "coolant_inlet_temperature_K",inletT, ...
    "charge_current_A",current, ...
    "charge_step_fraction",stepFraction, ...
    "charge_step_time_s",stepTime, ...
    "initial_battery_temperature_K",initialT, ...
    "max_cell_voltage_V",maxV);
end
